/**
 * What the generated identity validators accept and reject (notme-3e9c73).
 *
 * gen/ts/identity.zod.ts is generated by ley-line-open's released
 * capnpc-schema-bridge-zod plugin (pinned in schema/codegen/llo-release.json).
 * It replaced notme's hand-rolled capnp-to-ts.ts, and the switch changed what
 * the validators admit. This file pins each change, so a future plugin release
 * that moves any of them fails here and has to be reviewed.
 *
 * Stricter than before, and correct for a capnp schema:
 *   - objects are `.strict()`: an unknown key is rejected, not stripped;
 *   - a capnp union (Proof) is exactly one variant: `{}`, two variants, or a
 *     variant plus a stray key are rejected. The old schema made every
 *     variant optional and accepted all three.
 *
 * Looser than before (capnp absence semantics, LLO ADR-0004): an absent
 * scalar, enum, Data or List field is filled with its capnp zero value, so
 * `CABundleSchema.parse({})` succeeds with an empty signature, and a
 * BridgeCertResult without `scope` comes back as "bridgeCert". These schemas
 * are therefore NOT admission control for anything authority-bearing. No
 * production code parses with them: worker/src/gha-oidc.ts, cert-exchange.ts
 * and revocation.ts each validate their own JSON wire shapes, which the
 * fixtures below show these schemas do not describe.
 *
 * Unchanged: integer and UInt (nonnegative) checks, enum membership, bytes
 * as Uint8Array only.
 */
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { fileURLToPath } from "node:url";
import { describe, expect, it } from "vitest";
import {
  BridgeCertResultSchema,
  CABundleSchema,
  CertPairRequestSchema,
  CertRequestSchema,
  CertScopeSchema,
  GHAClaimsSchema,
  OracleInfoSchema,
  ProofSchema,
  RevocationReasonSchema,
  RevocationResultSchema,
} from "../../../gen/ts/identity.zod";

const ROOT = fileURLToPath(new URL("../../../", import.meta.url).href);
const BYTES = new Uint8Array([1, 2, 3]);
const BUNDLE = {
  epoch: 1,
  seqno: 2,
  keys: [{ kid: "k1", publicKey: BYTES }],
  keyId: "k1",
  prevKeyId: "",
  issuedAt: 1767225600,
  signature: BYTES,
};
const PAIR_REQUEST = {
  proof: { bootstrapCode: "c" },
  publicKeys: { mtls: "m", signing: "s" },
  proofs: { mtls: BYTES, signing: BYTES },
};

describe("identity.zod: unknown keys are rejected (strict)", () => {
  it("accepts a complete CABundle", () => {
    expect(CABundleSchema.safeParse(BUNDLE).success).toBe(true);
  });

  it.each([
    ["CABundle, top level", CABundleSchema, { ...BUNDLE, extra: 1 }],
    ["CABundle, inside a KeyEntry", CABundleSchema, { ...BUNDLE, keys: [{ kid: "k1", publicKey: BYTES, x: 1 }] }],
    ["CertPairRequest, inside publicKeys", CertPairRequestSchema, { ...PAIR_REQUEST, publicKeys: { mtls: "m", signing: "s", ca: "x" } }],
  ])("%s", (_, schema, value) => {
    const r = schema.safeParse(value);
    expect(r.success).toBe(false);
    expect(r.error?.issues[0]?.code).toBe("unrecognized_keys");
  });
});

describe("identity.zod: a Proof is exactly one variant", () => {
  it.each([["ghaOidc"], ["passkey"], ["bootstrapCode"]])("accepts the %s variant alone", (variant) => {
    const value = {
      ghaOidc: GHAClaimsSchema.parse({}),
      passkey: BYTES,
      bootstrapCode: "c",
    }[variant as "ghaOidc" | "passkey" | "bootstrapCode"];
    expect(ProofSchema.safeParse({ [variant]: value }).success).toBe(true);
  });

  it.each([
    ["no variant", {}],
    ["two variants", { bootstrapCode: "c", passkey: BYTES }],
    ["a variant plus a stray key", { bootstrapCode: "c", type: "bootstrap" }],
    ["a variant set to undefined", { bootstrapCode: undefined }],
    // The shape worker/src/cert-exchange.ts actually receives. The old
    // all-optional schema stripped it to `{}` and accepted it.
    ["the /cert/exchange `{type, token}` body", { type: "oidc", token: "eyJ" }],
  ])("rejects %s", (_, value) => {
    expect(ProofSchema.safeParse(value).success).toBe(false);
  });

  it("a CertPairRequest with an empty proof is rejected", () => {
    expect(CertPairRequestSchema.safeParse({ ...PAIR_REQUEST, proof: {} }).success).toBe(false);
  });
});

describe("identity.zod: enums, integers and bytes", () => {
  it("the scope and reason vocabularies are exactly the schema's enumerants", () => {
    expect([...CertScopeSchema.options]).toEqual(["bridgeCert", "authorityManage", "certMint"]);
    expect([...RevocationReasonSchema.options]).toEqual([
      "epochMismatch",
      "unknownKey",
      "rollbackAttack",
      "bundleInvalid",
      "bundleStale",
    ]);
  });

  it("rejects a scope outside the vocabulary, alone or in a list", () => {
    expect(CertScopeSchema.safeParse("root").success).toBe(false);
    expect(CertRequestSchema.safeParse({ scopes: ["bridgeCert", "root"], proof: { bootstrapCode: "c" } }).success).toBe(false);
  });

  it.each([
    ["a negative UInt32", { epoch: -1 }],
    ["a fractional UInt32", { epoch: 1.5 }],
    ["a numeric string", { epoch: "1" }],
    ["NaN", { seqno: Number.NaN }],
    ["Infinity", { seqno: Number.POSITIVE_INFINITY }],
    ["null", { epoch: null }],
    ["a fractional Int64", { issuedAt: 1.5 }],
  ])("rejects %s", (_, patch) => {
    expect(CABundleSchema.safeParse({ ...BUNDLE, ...patch }).success).toBe(false);
  });

  it("accepts a negative Int64 (issuedAt is signed in the schema)", () => {
    expect(CABundleSchema.safeParse({ ...BUNDLE, issuedAt: -5 }).success).toBe(true);
  });

  it.each([
    ["a base64 string", "AQID"],
    ["a number array", [1, 2, 3]],
    ["an ArrayBuffer", new ArrayBuffer(3)],
  ])("Data fields take a Uint8Array only, not %s", (_, signature) => {
    expect(CABundleSchema.safeParse({ ...BUNDLE, signature }).success).toBe(false);
  });

  it("parsed lists are frozen", () => {
    const parsed = CABundleSchema.parse(BUNDLE);
    expect(Object.isFrozen(parsed.keys)).toBe(true);
  });
});

describe("identity.zod: absent fields take capnp zero values (looser; not admission control)", () => {
  it("an empty object parses as an all-zero CABundle with no signature", () => {
    const parsed = CABundleSchema.parse({});
    expect(parsed).toMatchObject({ epoch: 0, seqno: 0, keys: [], keyId: "", prevKeyId: "", issuedAt: 0 });
    expect(parsed.signature).toBeInstanceOf(Uint8Array);
    expect(parsed.signature.length).toBe(0);
  });

  it("a BridgeCertResult without scope comes back as the zeroth enumerant, bridgeCert", () => {
    const parsed = BridgeCertResultSchema.parse({ certificate: "c", expiresAt: 1, subject: "s" });
    expect(parsed.scope).toBe("bridgeCert");
  });

  it("an empty RevocationResult reads as not revoked", () => {
    expect(RevocationResultSchema.parse({})).toEqual({ revoked: false, reason: "epochMismatch" });
  });

  it("a struct-typed field has no default: a CertPairRequest still needs all three members", () => {
    expect(CertPairRequestSchema.safeParse({ proof: { bootstrapCode: "c" } }).success).toBe(false);
  });

  it("OracleInfo {} parses as no keys, no scopes, epoch 0", () => {
    expect(OracleInfoSchema.parse({})).toEqual({ keys: [], scopes: [], epoch: 0 });
  });
});

describe("identity.zod: real producers' JSON is not what these schemas describe", () => {
  // The worker serves CABundle JSON with `keys` as a kid → base64 map and the
  // signature as base64 (schema/fixtures/, revocation.ts). The generated
  // schema models the capnp struct (List(KeyEntry), Data), so it rejects the
  // JSON. The old schema rejected it too.
  it.each([["cabundle-basic"], ["cabundle-multikey"], ["cabundle-rotation"]])("rejects the %s fixture", (name) => {
    const json = JSON.parse(readFileSync(join(ROOT, "schema/fixtures", `${name}.json`), "utf8"));
    const r = CABundleSchema.safeParse(json);
    expect(r.success).toBe(false);
    expect(r.error?.issues.map((i) => i.path.join("."))).toContain("keys");
  });

  it("rejects a GitHub Actions OIDC payload, whose claims are snake_case", () => {
    const payload = {
      iss: "https://token.actions.githubusercontent.com",
      sub: "repo:o/r:ref:refs/heads/main",
      aud: "notme.bot",
      exp: 2,
      iat: 1,
      jti: "j",
      repository: "o/r",
      repository_owner: "o",
      ref: "refs/heads/main",
      sha: "s",
      actor: "a",
      workflow: "w",
      job_workflow_ref: "o/r/.github/workflows/w.yml@refs/heads/main",
      run_id: "1",
      event_name: "push",
      environment: "",
    };
    expect(GHAClaimsSchema.safeParse(payload).success).toBe(false);
  });
});
